insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_criteria','criteria','noun','standards used to judge, choose, or decide something','[{"senseId":"criteria_1","meaning":"standards used to judge, choose, or decide something","acceptedParaphrases":["standards","rules for judging"],"masteryContexts":[{"contextId":"u1_41_criteria_meaning","text":"Speed and accuracy are two of the criteria used to select the team.","meaning":"measures by which choices are judged","wrongMeanings":["scores collected after a final match","rules explaining how to play a sport","names of players chosen for a squad"]},{"contextId":"u1_41_criteria_paraphrase","text":"The judges use several criteria when deciding the winner.","meaning":"conditions used for evaluating choices","wrongMeanings":["prizes offered to the competition winners","questions asked after each performance","opinions shared by members of the audience"]}],"situationDistractors":["The judges chose the winner by guessing.","Their judges awarded gold, silver and bronze medals.","The winner''s name was written on the trophy.","The panel met at nine o''clock to start the contest.","Last year’s winners received medals, a shiny trophy and a free trip to the capital.","The competition results will be displayed on the school notice board this evening, after lessons.","The winners will be announced on the school website early next week.","The local newspaper printed the fixtures for the whole month on page three."],"gapDistractors":[{"contextId":"u1_41_criteria_gap_meaning_sentence","answer":"criteria","wrong":["rewards","tickets","staff"]},{"contextId":"u1_41_criteria_gap_x1","answer":"criteria","wrong":["trophies","whistles","staff"]},{"contextId":"u1_41_criteria_gap_x2","answer":"criteria","wrong":["trophies","staff","holidays"]}],"spellingErrors":["criterea","critiria","criteriea","cryteria","critera","criterria"],"masteryPassages":[{"passageId":"u1_41_criteria_passage_1","contextId":"u1_41_criteria_gap_meaning_sentence","text":"The judges met before the competition started. They agreed on the ____: originality, effort and presentation each counted for a third of the marks.","answer":"criteria"},{"passageId":"u1_41_criteria_passage_2","contextId":"u1_41_criteria_gap_x1","text":"Not everyone can join the programme. Applicants must meet several ____, including a minimum age and a recommendation from a teacher.","answer":"criteria"}],"contextDependentParaphrases":[],"wrongParaphrases":["results","opinions","rewards"],"misleadingDistractors":["results","opinions","evidence"],"teacherNote":"Plural of criterion; use standards used for judging as the core meaning."}]'::jsonb,'[]'::jsonb,'["selection criteria","meet the criteria"]'::jsonb,'live'),
('vocab_historic','historic','adjective','important in history or likely to be remembered for a long time','[{"senseId":"historic_1","meaning":"important in history or likely to be remembered for a long time","acceptedParaphrases":["important and memorable","historically important","momentous"],"masteryContexts":[{"contextId":"u1_42_historic_meaning","text":"The victory was a historic moment for the small club, and fans still talk about it.","meaning":"important enough to be remembered for years","wrongMeanings":["old enough to be placed in a museum","celebrated only by supporters of one team","arranged long before the final took place"]},{"contextId":"u1_42_historic_paraphrase","text":"The opening of the first women’s league was a historic day for the sport.","meaning":"important enough to change what happens later","wrongMeanings":["sad enough to be remembered by everyone","busy enough to fill the whole calendar","early enough to be listed in the printed programme"]}],"situationDistractors":["The ground was old and the seats were uncomfortable.","The match was an ordinary league game that nobody remembers.","The stadium is quite new and has modern lights.","The museum next to the stadium sells cheap souvenirs.","The old football ground was knocked down and replaced with a large car park.","Last weekend’s match was a quiet event that very few people will talk about later.","Heavy rain delayed the start of the match, so spectators waited under umbrellas.","The club cancelled its annual dinner after the venue flooded last winter.","A heavy thunderstorm flooded the stadium car park during yesterday’s match."],"gapDistractors":[{"contextId":"u1_42_historic_gap_meaning_sentence","answer":"historic","wrong":["routine","forgettable","trivial"]},{"contextId":"u1_42_historic_gap_x1","answer":"historic","wrong":["forgettable","routine","trivial"]},{"contextId":"u1_42_historic_gap_x2","answer":"historic","wrong":["reasonable","honest","optional"]}],"spellingErrors":["historick","histroic","hystoric","historec","historik","historyc"],"wordFamilyForms":[{"form":"historic","partOfSpeech":"adjective","example":"The opening of the new stadium was a historic occasion for the town.","pedagogicallyUseful":true},{"form":"history","partOfSpeech":"noun","example":"The club has a long and proud history.","pedagogicallyUseful":true},{"form":"historical","partOfSpeech":"adjective","example":"The museum displays historical objects connected with the sport.","pedagogicallyUseful":true},{"form":"historian","partOfSpeech":"noun","example":"A local historian wrote a book about the early years of the club.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u1_42_historic_passage_1","contextId":"u1_42_historic_gap_meaning_sentence","text":"The two countries had been enemies for decades. When they signed the peace agreement, it was a ____ day that children will study in school for generations.","answer":"historic"},{"passageId":"u1_42_historic_passage_2","contextId":"u1_42_historic_gap_x1","text":"The town is popular with visitors. Tourists come from all over the world to see its ____ centre, with a castle and narrow streets from the Middle Ages.","answer":"historic"}],"contextDependentParaphrases":[],"wrongParaphrases":["old and out of date","dull and ordinary","recent and unimportant"],"misleadingDistractors":["old-fashioned","ordinary","recent"],"teacherNote":"Means important in history, not simply old or related to history."}]'::jsonb,'["history","historical","historian"]'::jsonb,'["historic victory","historic moment"]'::jsonb,'live'),
('vocab_selection','selection','noun','a range of things available to choose from or the act of choosing','[{"senseId":"selection_1","meaning":"a range of things available to choose from or the act of choosing","acceptedParaphrases":["choice","range"],"masteryContexts":[{"contextId":"u1_43_selection_meaning","text":"The shop has a wide selection of equipment for different sports.","meaning":"range of available choices","wrongMeanings":["place where goods are stored","list of prices for each item","person who helps customers to buy"]},{"contextId":"u1_43_selection_paraphrase","text":"The centre offers a wide selection of after-school activities.","meaning":"set from which items are chosen","wrongMeanings":["timetable showing when classes begin","fee paid to join a club","group of staff who run the centre"]}],"situationDistractors":["The coach refused to choose anyone for the team.","The shop sells only one kind of football boot.","Our club had to reject every player who applied.","Every item in the shop was sold out by noon.","Our coach asked every player to hand in their kit at the end of the season.","Heavy snow forced the organisers to cancel all of the outdoor events this weekend.","The match was postponed because the referee fell ill that morning."],"gapDistractors":[{"contextId":"u1_43_selection_gap_meaning_sentence","answer":"selection","wrong":["amount","number","quantity"]},{"contextId":"u1_43_selection_gap_x1","answer":"selection","wrong":["refusal","demand","result"]},{"contextId":"u1_43_selection_gap_x2","answer":"selection","wrong":["speed","weight","height"]}],"spellingErrors":["selecsion","selektion","selction","selecttion","sellection","selectian"],"wordFamilyForms":[{"form":"selection","partOfSpeech":"noun","example":"The shop offers a wide selection of running shoes.","pedagogicallyUseful":true},{"form":"select","partOfSpeech":"verb","example":"Coaches will select the final team on Friday.","pedagogicallyUseful":true,"altExample":"The teacher will select five students to represent the school in the relay."},{"form":"selective","partOfSpeech":"adjective","example":"The academy is very selective about the players it accepts.","pedagogicallyUseful":true,"altExample":"The club is very selective about who joins the senior team."}],"masteryPassages":[{"passageId":"u1_43_selection_passage_1","contextId":"u1_43_selection_gap_meaning_sentence","text":"Whatever kind of book you like, you will find it here. The library has a huge ____ of titles, from detective stories to science fiction.","answer":"selection"},{"passageId":"u1_43_selection_passage_2","contextId":"u1_43_selection_gap_x1","text":"After the trials, the final ____ of the team will be announced on Friday. Only fifteen players will make the squad.","answer":"selection"}],"contextDependentParaphrases":[],"wrongParaphrases":["warning","payment","gift"],"misleadingDistractors":["lack of options","warning","payment"]}]'::jsonb,'["select","selective"]'::jsonb,'["wide selection","selection process"]'::jsonb,'live'),
('vocab_produce','produce','verb','to make, create, or cause something to exist','[{"senseId":"produce_1","meaning":"to make, create, or cause something to exist","acceptedParaphrases":["make","create"],"masteryContexts":[{"contextId":"u1_44_produce_meaning","text":"Local craftspeople produce new bats from wood, one at a time.","meaning":"bring something into existence","wrongMeanings":["repair something that has been broken","sell something to a customer","take something away from a place"]},{"contextId":"u1_44_produce_paraphrase","text":"The workshop produces specialist equipment for local teams.","meaning":"create or manufacture something","wrongMeanings":["store something safely for later use","deliver something to a new address","check something before delivery"]}],"situationDistractors":["The factory closed and stopped making anything.","The workshop repaired old racquets for local players.","The club sold its old equipment to another school.","The shop imported all its bats from abroad.","The factory closed after the fire, and most of the local workers lost their jobs.","Very few people attend the home matches, because the tickets have become far too expensive for families.","The mayor opened the new sports centre with a short speech and ribbon.","One referee checked the pitch before allowing both teams onto the grass."],"gapDistractors":[{"contextId":"u1_44_produce_gap_base_noun","answer":"produce","wrong":["borrow","describe","advertise"]},{"contextId":"u1_44_produce_gap_third_noun","answer":"produces","wrong":["destroys","avoids","forgets"]},{"contextId":"u1_44_produce_gap_past_noun","answer":"produced","wrong":["avoided","forgot","purchased"]},{"contextId":"u1_44_produce_gap_perfect_noun","answer":"produced","wrong":["travelled","arrived","complained"]},{"contextId":"u1_44_produce_gap_passive_present","answer":"produced","wrong":["complained","escaped","arrived"]},{"contextId":"u1_44_produce_gap_passive_past","answer":"produced","wrong":["escaped","travelled","complained"]}],"spellingErrors":["prodouce","produse","prodduce","prodyce","produsse","producee"],"wordFamilyForms":[{"form":"produce","partOfSpeech":"verb","example":"The factory can produce thousands of footballs every week.","pedagogicallyUseful":true},{"form":"production","partOfSpeech":"noun","example":"The production of the new kit started in March.","pedagogicallyUseful":true},{"form":"producer","partOfSpeech":"noun","example":"The country is a leading producer of sports equipment.","pedagogicallyUseful":true},{"form":"product","partOfSpeech":"noun","example":"Their latest product is a lightweight running shoe.","pedagogicallyUseful":true},{"form":"productive","partOfSpeech":"adjective","example":"A short rest can make your next training session more productive.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u1_44_produce_passage_1","contextId":"u1_44_produce_gap_base_noun","text":"Winters are mild in this region. Farms here ____ enough vegetables to feed the whole city, even in the coldest months.","answer":"produce"},{"passageId":"u1_44_produce_passage_2","contextId":"u1_44_produce_gap_third_noun","text":"The factory is the biggest employer in the town. It ____ over a thousand bicycles every month and sells them all over Europe.","answer":"produces"}],"contextDependentParaphrases":[],"wrongParaphrases":["use","borrow","destroy"],"misleadingDistractors":["destroy","borrow","select"],"grammarForms":{"base":"produce","thirdPerson":"produces","past":"produced","pastParticiple":"produced","ing":"producing"},"grammarPatterns":["produce + noun","be produced + passive"],"teacherNote":"Use the verb sense make/create in this unit."}]'::jsonb,'["production","producer","product","productive"]'::jsonb,'[]'::jsonb,'live'),
('vocab_craftspeople','craftspeople','noun','people skilled at making things by hand','[{"senseId":"craftspeople_1","meaning":"people skilled at making things by hand","acceptedParaphrases":["skilled makers","artisans"],"masteryContexts":[{"contextId":"u1_45_craftspeople_meaning","text":"Local craftspeople make the wooden equipment using traditional methods.","meaning":"skilled workers who create objects by hand","wrongMeanings":["workers who sell goods in markets","people who design large buildings and public parks","managers who plan large sports events"]},{"contextId":"u1_45_craftspeople_paraphrase","text":"Visitors watched craftspeople shape clay bowls on spinning wheels at the village market.","meaning":"people trained to make objects with their hands","wrongMeanings":["traders who buy goods from other countries","performers who entertain crowds at festivals","guides who show tourists around the whole village"]}],"situationDistractors":["Large crowds of fans filled the stands.","The coaches trained the team for the final.","Machines in a factory stamped out thousands of identical bats.","Customers queued outside the sports shop at the weekend.","Last weekend, thousands of fans filled the stadium to cheer for their favourite local team.","Professional athletes were paid very large fees, and they appeared in the new television advert.","Famous footballers signed autographs for fans outside the stadium after the match.","Parents queued outside the school hall to collect their children’s certificates."],"gapDistractors":[{"contextId":"u1_45_craftspeople_gap_meaning_sentence","answer":"craftspeople","wrong":["spectators","customers","staff"]},{"contextId":"u1_45_craftspeople_gap_x1","answer":"craftspeople","wrong":["spectators","customers","staff"]},{"contextId":"u1_45_craftspeople_gap_x2","answer":"craftspeople","wrong":["spectators","customers","staff"]}],"spellingErrors":["craftspeeple","craftpeople","craftspeaple","craftspeepal","craftspeoples","craftsepople"],"masteryPassages":[{"passageId":"u1_45_craftspeople_passage_1","contextId":"u1_45_craftspeople_gap_meaning_sentence","text":"The summer fair was busy all weekend. Local ____ sold hand-made pottery, wooden toys and woven baskets, and visitors could watch them at work.","answer":"craftspeople"},{"passageId":"u1_45_craftspeople_passage_2","contextId":"u1_45_craftspeople_gap_x1","text":"The old theatre had been damaged by fire. Its restoration required talented ____ who could carve stone and repair delicate wooden panels.","answer":"craftspeople"}],"contextDependentParaphrases":[],"wrongParaphrases":["keen spectators","paid athletes","loyal customers"],"misleadingDistractors":["spectators","athletes","staff"]}]'::jsonb,'[]'::jsonb,'[]'::jsonb,'live'),
('vocab_significant','significant','adjective','important or large enough to be noticed or have an effect','[{"senseId":"significant_1","meaning":"important or large enough to be noticed or have an effect","acceptedParaphrases":["important","notable"],"masteryContexts":[{"contextId":"u1_46_significant_meaning","text":"The new training programme led to a significant improvement in results, much bigger than anyone expected.","meaning":"important enough to have an effect","wrongMeanings":["unusual enough to need an explanation","recent enough to be included in reports","obvious enough to be seen from far away"]},{"contextId":"u1_46_significant_paraphrase","text":"Regular exercise can have a significant effect on mental wellbeing.","meaning":"meaningful enough to make a difference","wrongMeanings":["pleasant enough to be enjoyed by everyone","simple enough to be understood quickly","rare enough to be hard to explain"]}],"situationDistractors":["The change in the rules made only a tiny difference.","The new boots were famous but ordinary in design.","The improvement was so small that nobody in the team noticed it.","The result of the match did not matter to anyone.","The tiny scratch on the bat did not affect its performance in any way.","Nobody noticed the minor change to the timetable, because it affected so few students.","Several fans left early because the match finished in a boring draw.","Her head teacher announced that the school would build a new gymnasium before the summer.","The head teacher announced that parents had raised enough money to build a brand new gymnasium before summer."],"gapDistractors":[{"contextId":"u1_46_significant_gap_meaning_sentence","answer":"significant","wrong":["slight","minor","tiny"]},{"contextId":"u1_46_significant_gap_x1","answer":"significant","wrong":["slight","tiny","small"]},{"contextId":"u1_46_significant_gap_x2","answer":"significant","wrong":["disappointing","negative","dangerous"]}],"spellingErrors":["signifacant","significent","signficant","signifficant","significat","sinificant"],"wordFamilyForms":[{"form":"significant","partOfSpeech":"adjective","example":"There was a significant improvement in her times after three months.","pedagogicallyUseful":true},{"form":"significance","partOfSpeech":"noun","example":"The coach explained the significance of warming up properly.","pedagogicallyUseful":true,"altExample":"The coach explained the significance of each change to the starting line-up."},{"form":"significantly","partOfSpeech":"adverb","example":"Her fitness has improved significantly since September.","pedagogicallyUseful":true,"altExample":"Her times have improved significantly since she began training with the club."}],"masteryPassages":[{"passageId":"u1_46_significant_passage_1","contextId":"u1_46_significant_gap_meaning_sentence","text":"The school started a cycling campaign last year. There has been a ____ rise in the number of students using bicycles, from forty to over two hundred.","answer":"significant"},{"passageId":"u1_46_significant_passage_2","contextId":"u1_46_significant_gap_x1","text":"Few people noticed the small change at the time. It turned out to be ____: it later led to a completely new way of teaching.","answer":"significant"}],"contextDependentParaphrases":[],"wrongParaphrases":["tiny","ordinary","unnecessary"],"misleadingDistractors":["famous","ordinary","controversial"],"teacherNote":"Do not accept big automatically. The unit sense is important/notable or large enough to have an effect."}]'::jsonb,'["significance","significantly"]'::jsonb,'["significant increase","significant difference","significant impact"]'::jsonb,'live'),
('vocab_expansion','expansion','noun','an increase in size, range, or amount','[{"senseId":"expansion_1","meaning":"an increase in size, range, or amount","acceptedParaphrases":["growth","increase"],"masteryContexts":[{"contextId":"u1_47_expansion_meaning","text":"The club’s expansion created space for several new sports.","meaning":"process of becoming larger in scope","wrongMeanings":["process of moving to a new location","decision to close an old facility","plan to reduce the cost of membership"]},{"contextId":"u1_47_expansion_paraphrase","text":"The expansion of the league has attracted more young players.","meaning":"growth in size, range or amount","wrongMeanings":["change in the rules of the league","loss of money during the season","delay in the start of the matches"]}],"situationDistractors":["Her club closed two of its three sports halls.","The number of players stayed exactly the same for years.","The league moved all its matches to a new day.","His new coach changed the team''s training routine.","The club closed two of its youth teams because there was not enough money.","The population of the village fell steadily, as young people moved away to study in the city.","The head coach resigned after the team lost six matches in a row.","Heavy traffic delayed the visiting team’s coach on the motorway yesterday."],"gapDistractors":[{"contextId":"u1_47_expansion_gap_meaning_sentence","answer":"expansion","wrong":["reduction","closure","decline"]},{"contextId":"u1_47_expansion_gap_x1","answer":"expansion","wrong":["closure","reduction","decline"]},{"contextId":"u1_47_expansion_gap_x2","answer":"expansion","wrong":["reduction","closure","decline"]}],"spellingErrors":["expantion","expanshion","expension","expanssion","expandsion","expasion"],"wordFamilyForms":[{"form":"expansion","partOfSpeech":"noun","example":"The expansion of the sports centre created space for a new pool.","pedagogicallyUseful":true},{"form":"expand","partOfSpeech":"verb","example":"The club plans to expand its youth programme next year.","pedagogicallyUseful":true,"altExample":"The school plans to expand the sports hall by adding two more courts."},{"form":"expanding","partOfSpeech":"adjective","example":"The expanding league now includes twelve teams.","pedagogicallyUseful":true,"altExample":"An expanding fan base meant the stadium needed more seats.","note":"Participial adjective."}],"masteryPassages":[{"passageId":"u1_47_expansion_passage_1","contextId":"u1_47_expansion_gap_meaning_sentence","text":"The airport is building a second terminal. The ____ of the airport means that it will soon handle twice as many passengers as before.","answer":"expansion"},{"passageId":"u1_47_expansion_passage_2","contextId":"u1_47_expansion_gap_x1","text":"More families are moving to the city every year. Rapid ____ has pushed new housing further into the countryside.","answer":"expansion"}],"contextDependentParaphrases":[],"wrongParaphrases":["reduction","delay","selection"],"misleadingDistractors":["reduction","delay","selection"]}]'::jsonb,'["expand","expanding"]'::jsonb,'["rapid expansion","business expansion"]'::jsonb,'live'),
('vocab_reputation','reputation','noun','the general opinion people have about someone or something','[{"senseId":"reputation_1","meaning":"the general opinion people have about someone or something","acceptedParaphrases":["public image","general opinion"],"masteryContexts":[{"contextId":"u1_48_reputation_meaning","text":"The academy has a strong reputation for developing young athletes.","meaning":"shared opinion others have formed","wrongMeanings":["private feeling someone keeps secret","official list of the academy’s rules","written record of every student’s grades"]},{"contextId":"u1_48_reputation_paraphrase","text":"The reputation of the club improved after the campaign.","meaning":"public judgement built over time","wrongMeanings":["advertisement paid for by the club","financial balance kept by the club","group of volunteers working for the club"]}],"situationDistractors":["The academy moved to a new address last year.","Their club''s yearly fee is paid in two instalments.","The academy has twenty coaches and four pitches.","Our academy was founded by a former champion.","Her coach changed the team’s training time without telling any of the players.","She won three gold medals in a single afternoon, at her very first national competition.","Tickets for the school concert are available from the main office until the end of the week.","Most spectators brought umbrellas because rain was forecast for the afternoon.","Several students collected their certificates from the main office."],"gapDistractors":[{"contextId":"u1_48_reputation_gap_meaning_sentence","answer":"reputation","wrong":["permission","salary","timetable"]},{"contextId":"u1_48_reputation_gap_x1","answer":"reputation","wrong":["permission","uniform","timetable"]},{"contextId":"u1_48_reputation_gap_x2","answer":"reputation","wrong":["permission","timetable","uniform"]}],"spellingErrors":["repution","reputaton","reputasion","repetation","reputashun","reputtation"],"wordFamilyForms":[{"form":"reputation","partOfSpeech":"noun","example":"The academy has an excellent reputation for coaching young athletes.","pedagogicallyUseful":true},{"form":"reputable","partOfSpeech":"adjective","example":"Always buy sports equipment from a reputable shop.","pedagogicallyUseful":true,"altExample":"Only reputable companies were allowed to sell tickets for the tournament."},{"form":"disreputable","partOfSpeech":"adjective","example":"Fans were angry that the club had worked with a disreputable agent.","pedagogicallyUseful":true,"altExample":"The disreputable agent was banned from every club in the league."}],"masteryPassages":[{"passageId":"u1_48_reputation_passage_1","contextId":"u1_48_reputation_gap_meaning_sentence","text":"The restaurant is always full. It has an excellent ____ in the town: people travel for miles because everyone says the food is wonderful.","answer":"reputation"},{"passageId":"u1_48_reputation_passage_2","contextId":"u1_48_reputation_gap_x1","text":"Trust is easy to lose. One careless lie can damage a person’s ____ for years, because it takes a long time for others to believe you again.","answer":"reputation"}],"contextDependentParaphrases":[],"wrongParaphrases":["official rank","private opinion","personal achievement"],"misleadingDistractors":["achievement","official rank","private opinion"]}]'::jsonb,'["reputable","disreputable"]'::jsonb,'["good reputation","build a reputation"]'::jsonb,'live'),
('vocab_reasonable','reasonable','adjective','fair, sensible, or not too expensive or extreme','[{"senseId":"reasonable_1","meaning":"fair, sensible, or not too expensive or extreme","acceptedParaphrases":["fair","sensible"],"masteryContexts":[{"contextId":"u1_49_reasonable_meaning","text":"The entry fee is reasonable for a full day of activities, so most families are happy to pay.","meaning":"fair or sensible, not excessive","wrongMeanings":["unusually high for a single day","completely free for every visitor","fixed by law for all clubs"]},{"contextId":"u1_49_reasonable_paraphrase","text":"Most students thought the membership fee was reasonable.","meaning":"within an acceptable moderate limit","wrongMeanings":["too low for the club to survive","higher than at any other club","paid early by nearly all the students"]}],"situationDistractors":["The entry fee was far too high for most families.","The gym membership cost more than most students could ever pay.","Nobody in the club could understand the strange new rule about fees.","The tickets for the final were free for every student.","The cost of entering the competition was far too high for most families.","The referee’s rude and unfair decision annoyed both teams as well as the whole noisy crowd.","The sports hall closes for cleaning every weekend afternoon.","The school fundraiser raised enough money for new equipment, and the headteacher thanked every parent."],"gapDistractors":[{"contextId":"u1_49_reasonable_gap_meaning_sentence","answer":"reasonable","wrong":["excessive","enormous","unaffordable"]},{"contextId":"u1_49_reasonable_gap_x1","answer":"reasonable","wrong":["ridiculous","terrible","huge"]},{"contextId":"u1_49_reasonable_gap_x2","answer":"reasonable","wrong":["silly","foolish","absurd"]}],"spellingErrors":["reasonible","resonable","reasonnable","reasonabal","reasenable","reasonble"],"wordFamilyForms":[{"form":"reasonable","partOfSpeech":"adjective","example":"The price of the tickets seemed reasonable for such an important match.","pedagogicallyUseful":true},{"form":"reasonably","partOfSpeech":"adverb","example":"The team played reasonably well in the first half.","pedagogicallyUseful":true},{"form":"unreasonable","partOfSpeech":"adjective","example":"Many students felt that the homework deadline was unreasonable.","pedagogicallyUseful":true},{"form":"reason","partOfSpeech":"noun","example":"The coach gave no reason for dropping the captain.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u1_49_reasonable_passage_1","contextId":"u1_49_reasonable_gap_meaning_sentence","text":"The hotel was clean and close to the beach. The price was ____, so we decided to stay for the whole week.","answer":"reasonable"},{"passageId":"u1_49_reasonable_passage_2","contextId":"u1_49_reasonable_gap_x1","text":"Everyone in the class had been working since morning. \"It is perfectly ____ to ask for a break after three hours,\" the teacher said.","answer":"reasonable"}],"contextDependentParaphrases":[],"wrongParaphrases":["odd","excessive","impossible"],"misleadingDistractors":["excessive","impossible","historic"],"teacherNote":"Use the fair/sensible/not excessive sense in this unit."}]'::jsonb,'["reasonably","unreasonable","reason"]'::jsonb,'["reasonable price","reasonable explanation"]'::jsonb,'live'),
('vocab_antiques','antiques','noun','old objects that are valuable or interesting because of their age','[{"senseId":"antiques_1","meaning":"old objects that are valuable or interesting because of their age","acceptedParaphrases":["valuable old objects","collectable old items"],"masteryContexts":[{"contextId":"u1_50_antiques_meaning","text":"The market sells antiques alongside handmade sports memorabilia.","meaning":"valuable old objects kept for interest","wrongMeanings":["modern goods sold at low prices","copies of famous sports trophies","damaged items waiting to be thrown away"]},{"contextId":"u1_50_antiques_paraphrase","text":"Collectors travelled to the fair to buy antiques.","meaning":"collectable objects from an earlier period","wrongMeanings":["expensive tools used by professionals","rare plants grown for display","recent products made by talented local artists"]}],"situationDistractors":["The shop sold brand-new trainers in every colour.","The museum showed photographs of last year''s final.","Collectors paid a high price for a famous player''s signed shirt.","The market sold fresh fruit and vegetables every morning.","Every year the town holds a fashion show to promote clothes from young designers.","The shop sells modern gadgets, brand new phones and the latest computer games for teenagers.","Visitors to the market bought fresh vegetables, cheese and bread from local farmers.","The stadium café offers hot drinks, sandwiches and cakes throughout the afternoon."],"gapDistractors":[{"contextId":"u1_50_antiques_gap_meaning_sentence","answer":"antiques","wrong":["rumours","injuries","deadlines"]},{"contextId":"u1_50_antiques_gap_x1","answer":"antiques","wrong":["rumours","bruises","deadlines"]},{"contextId":"u1_50_antiques_gap_x2","answer":"antiques","wrong":["rumours","injuries","storms"]}],"spellingErrors":["antikes","antiqes","antiqus","anteques","antiquies","antikeys"],"masteryPassages":[{"passageId":"u1_50_antiques_passage_1","contextId":"u1_50_antiques_gap_meaning_sentence","text":"Grandfather loves visiting markets at weekends. His house is full of ____: clocks, lamps and furniture from the nineteenth century.","answer":"antiques"},{"passageId":"u1_50_antiques_passage_2","contextId":"u1_50_antiques_gap_x1","text":"The shop on the corner is full of old things. It buys and sells ____, so you can find old coins, silver spoons and even Victorian mirrors.","answer":"antiques"}],"contextDependentParaphrases":[],"wrongParaphrases":["cheap modern furniture","small gift items","rare printed documents"],"misleadingDistractors":["new equipment","souvenirs","documents"]}]'::jsonb,'[]'::jsonb,'["antique market","valuable antiques"]'::jsonb,'live')
insert into public.vocabulary_unit_occurrences
(occurrence_id,vocabulary_id,unit_number,unit_title,set_number,position_in_unit,sense_id,status,active)
